fn main(){ let p=std::env::args().nth(1).unwrap(); let b=std::fs::read(&p).unwrap(); println!("sniff {:?}", rabbithole_gfx::image::sniff(&b)); let r=avif_parse::read_avif(&mut std::io::Cursor::new(&b)); match &r { Ok(d)=>println!("primary {} alpha {:?}", d.primary_item.len(), d.alpha_item.as_ref().map(|a|a.len())), Err(e)=>println!("err {e:?}") } let t=std::time::Instant::now(); let i=rabbithole_gfx::Image::decode(&b); println!("{:?} {:?}", i.map(|i|(i.width,i.height,i.pixel(i.width/2,i.height/2))), t.elapsed()); }
